(()=>{
const icon=id=>`<svg class="icon" aria-hidden="true"><use href="#ic-${id}"/></svg>`;
// Keep historical project figures distinct from demonstration dashboards.
const section=document.createElement('section');section.id='franchise-results';section.className='section wrap event-results';
section.innerHTML=`<div class="section-top"><div><div class="num">EVENT STRATEGY / 加盟展實績</div><h2>把展會人潮，變成招商成果。</h2></div><p>從企劃、預算與現場統籌，<br>一路接到展後跟進與加盟轉換。</p></div><div class="event-console"><div class="event-case-head"><span>${icon('signal')} 加盟展整合策劃</span><span>PROJECT EXPERIENCE / 匿名案例</span></div><div class="event-kpis"><article><span>專案投入</span><strong><small>約 NT$</small>80<em>萬</em></strong><p>預算、人力與展務統籌</p></article><article><span>有效名單</span><strong>480<em>筆</em></strong><p>現場需求辨識與紀錄</p></article><article><span>加盟成交</span><strong>17<em>組</em></strong><p>展後持續追蹤與轉換</p></article></div><div class="event-conversion" aria-label="專案成果路徑"><span>活動策略</span><i>→</i><span>480 筆有效名單</span><i>→</i><span>分級與持續跟進</span><i>→</i><strong>17 組加盟成交</strong></div><div class="event-bottom"><p>統籌範圍：活動企劃、預算、人力、物料、招商話術、現場動線與展後追蹤。</p><a href="#solutions" data-event-solution>查看活動解決方案 ↗</a></div><details class="event-method"><summary>展前到展後，怎麼把活動做成生意？<span>查看執行流程 ＋</span></summary><div class="event-method-content"><div class="event-flow" role="group" aria-label="活動執行流程">${[['target','策略與預算','STRATEGY'],['signal','宣傳與邀約','ACQUISITION'],['people','現場招商','ENGAGEMENT'],['chart','追蹤與成交','CONVERSION']].map((x,i)=>`<button type="button" data-event-stage="${i}" aria-pressed="${i===0}"><span>0${i+1}</span>${icon(x[0])}<b>${x[1]}</b><small>${x[2]}</small></button>${i<3?'<i class="event-arrow" aria-hidden="true">→</i>':''}`).join('')}</div><p class="event-readout" aria-live="polite">設定招商目標、預算與人力配置，整合物料、時程及現場執行表。</p><a href="#contact" class="event-brief">規劃我的下一場活動 ↗</a></div></details><p class="event-source">過往專案數據：投入為約數，依本人提供的歷史紀錄呈現。</p></div>`;
const results=document.querySelector('#view-results');results.prepend(section);
const notes=['設定招商目標、預算與人力配置，整合物料、時程及現場執行表。','整理招商主張、活動內容與邀約話術，追蹤來源及預約洽談。','規劃展位動線與接待節奏，記錄需求、意向與待跟進事項。','將名單分級派案、設定跟進節奏，以轉換漏斗及成本回看效益。'];
section.querySelectorAll('[data-event-stage]').forEach(b=>b.onclick=()=>{section.querySelectorAll('[data-event-stage]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));section.querySelector('.event-readout').textContent=notes[+b.dataset.eventStage]});
section.querySelector('[data-event-solution]').onclick=()=>document.querySelector('[data-bottleneck="0"]').click();
section.querySelector('.event-brief').onclick=()=>{document.querySelector('#need').value='活動策劃與招商轉換';document.querySelector('#problem').value='希望規劃活動企劃、招商流程與展後成交追蹤。'};
const d=section.querySelector('details');d.addEventListener('toggle',()=>d.querySelector('summary span').textContent=d.open?'收合執行流程 −':'查看執行流程 ＋');
const cap=document.querySelector('.capability-grid');
if(cap){const card=document.createElement('article');card.className='capability';card.innerHTML=`<div class="cap-top">${icon('signal')}<span>EVENTS & CONVERSION</span></div><h3>活動策劃與招商轉換</h3><p>加盟展、招商活動與品牌體驗，從策劃接到商機。</p><div>企劃與預算・宣傳邀約・現場統籌・名單追蹤・效益分析</div><a href="#contact">討論活動需求 ↗</a>`;card.querySelector('a').onclick=()=>document.querySelector('#need').value='活動策劃與招商轉換';cap.append(card);}
})();
